<?php
require_once __DIR__.'/../includes/auth.php';requireAdmin();
$users=$pdo->query("SELECT id,name,email,age,fitness_level,fitness_goal,dietary_preference,subscription_status,subscription_plan,subscription_expires_at,created_at FROM users WHERE role='user' ORDER BY created_at DESC")->fetchAll();$pageTitle='Manage users';require __DIR__.'/../includes/header.php';?>
<section class="page-heading"><div><p class="eyebrow">MEMBER DIRECTORY</p><h1>Manage users</h1><p>Review each member's fitness level, goals and membership status.</p></div></section><section class="panel"><div class="table-wrap"><table><thead><tr><th>Member</th><th>Fitness level</th><th>Goal</th><th>Membership</th><th>Expiry</th><th>Details</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><strong><?=e($u['name'])?></strong><br><small><?=e($u['email'])?></small></td><td><?=e(ucfirst($u['fitness_level']==='advanced'?'expert':($u['fitness_level']??'—')))?></td><td><?=e(ucwords(str_replace('_',' ',$u['fitness_goal']??'—')))?></td><td><?=e(($u['subscription_status']??'normal')==='active'?'Premium':'Normal (Free)')?> <?=e($u['subscription_status']==='active'?($u['subscription_plan']??''):'')?></td><td><?=e($u['subscription_expires_at']??'—')?></td><td><a class="button light btn-small" href="user-detail.php?id=<?=(int)$u['id']?>">View profile</a></td></tr><?php endforeach;?></tbody></table></div></section><?php require __DIR__.'/../includes/footer.php';?>
